{"source":"#include<stdio.h>
int main(int argc, char *argv[])
{
    long long int i , j ,k , l ,m ,n, counter=0 ,ct=0,a,b,c;
    scanf("%lld" , &n);
    while(n>0)
    {
        a = n%10;
        counter++;
        if(a==4 || a==7)
        {
            ct++;
        }
        n = n/10;
    }
    if(ct==4 || ct==7 || ct==counter)
    {
        printf("YES\n");
    }
    else
    {
        printf("NO\n");
    }
    return 0;
}"}
